  `firstName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lastName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fullName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dateOfBirth` datetime(3) NOT NULL,
  `gender` enum('male','female','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `bloodGroup` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `religion` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT 'general',
  `parentId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `classId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sectionId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `academicYearId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `schoolId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `addressStreet` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `addressCity` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `addressState` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `addressPincode` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergencyName` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergencyPhone` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergencyRel` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `house` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `previousSchool` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `aadhaarNumber` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `medicalNote` text COLLATE utf8mb4_unicode_ci,
